  const {response,body}=await request('/model-groups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:g.id,name:g.name,description:g.description,profileIds:profiles,expectedConfigHash:hash,...(g.role?{role:g.role}:{}),...change})});
  if(epoch!==connectionEpoch||feed!==(chatView&&chatView.feedId)){settingsGroupUnknown=true;return;}
