  if(!body||!Array.isArray(body.modelGroups)||typeof body.configHash!=='string'){settingsGroupUnknown=true;return;}
  settingsGen.catalog=(settingsGen.catalog||0)+1;if(settingsCatalog?.configHash===hash)settingsCatalog=body;
